export const BODY: string = "\n<p>تضاد تصویر کے سب سے گہرے اور سب سے ہلکے حصوں کے درمیان فرق ہے۔ یہی وہ ہے جو تصویر کو مضبوط اور ٹھوس محسوس کراتا ہے، یا چپٹا اور سرمئی۔</p>\n<p>اچھے تضاد والی تصویر میں گہرے سائے، روشن جھلکیاں، اور گہرائی کا واضح احساس ہوتا ہے۔ کم تضاد والی تصویر دھندلی لگتی ہے، جیسے وہ دھند سے لی گئی ہو۔</p>\n<p>یہ رہنما بتاتا ہے کہ تضاد کیسے کام کرتا ہے، سلائیڈر اور پری سیٹ اچھی طرح کیسے استعمال کریں، اور جھلکیاں کاٹے یا سائے کچلے بغیر مضبوطی کیسے شامل کریں۔ اس میں پورٹریٹ، منظر، اسکرین شاٹ، اور وہ غلطیاں شامل ہیں جو اچھی تصویر خراب کرتی ہیں۔ مفت <a href=\"/ur/tasveer-ka-contrast-badlein/\">Image Contrast Editor</a> مشق کی جگہ ہے: تصویر گھسیٹیں، سلائیڈر منتقل کریں، اور تفصیل کھوئے بغیر مضبوطی دکھائی دینا دیکھیں۔</p>\n<h2 id=\"what-contrast-does\">تضاد دراصل کیا کرتا ہے</h2>\n<p>تضاد تصویر کی لہجہ حد کو کھینچتا یا نچوڑتا ہے۔ اسے بڑھانے سے گہرے پکسل گہرے اور ہلکے پکسل ہلکے ہو جاتے ہیں، ان کے درمیان فرق چوڑا کرتے ہوئے۔</p>\n<p>تضاد کم کرنے سے الٹا ہوتا ہے۔ یہ گہرے اور ہلکے کو قریب لاتا ہے، تصویر کو نرم کرتا ہے اور اس کے سب سے روشن اور سب سے گہرے حصوں کے درمیان فرق کم کرتا ہے۔</p>\n<p>تضاد مجموعی چمک کو زیادہ نہیں بدلتا۔ اعلیٰ تضاد والی تصویر مجموعی طور پر گہری یا ہلکی ہو سکتی ہے، مگر اس کے سائے اور جھلکیاں کسی بھی طرح دور ہوں گے۔</p>\n<h2 id=\"why-photos-look-flat\">تصویریں چپٹی کیوں لگتی ہیں</h2>\n<p>دھند چپٹی تصویر کی سب سے عام وجہ ہے۔ دھند، کہرا، اور نم ہوا روشنی بکھیرتی ہے، جو سائے اٹھاتی ہے اور جھلکیاں دھیمی کرتی ہے جب تک پوری تصویر درمیان میں نہ بیٹھ جائے۔</p>\n<p>ابر آلود روشنی بھی تصویروں کو چپٹا کرتی ہے۔ بادل والا آسمان نرم، برابر روشنی دیتا ہے بغیر مضبوط سائے کے، اس لیے تصویر میں شروع سے کم لہجہ حد ہوتی ہے۔</p>\n<p>اسکین شدہ پرانی تصویریں بھی اکثر چپٹی لگتی ہیں۔ عمر پرنٹ کو دھندلا کرتی ہے، اسکینر لہجے غلط پڑھتے ہیں، اور نتیجہ سرمئی، دھندلی تصویر ہے بغیر گہرے کالے یا روشن سفید کے۔</p>\n<h2 id=\"slider-explained\">تضاد سلائیڈر، وضاحت</h2>\n<p>تضاد سلائیڈر منفی سے مثبت قیمتوں تک چلتا ہے، صفر کا مطلب کوئی تبدیلی نہیں۔ اسے دائیں منتقل کرنے سے تضاد بڑھتا ہے، اور بائیں منتقل کرنے سے کم ہوتا ہے۔</p>\n<p>چھوٹی حرکتیں بڑا فرق ڈالتی ہیں۔ 10 سے 20 فیصد کی تبدیلی اکثر چپٹی تصویر درست کرنے کے لیے کافی ہے، اور بڑی حرکتیں جلد جھلکیاں کاٹتی ہیں اور سائے کچلتی ہیں۔</p>\n<p>ٹول اپ لوڈ کے فوراً بعد آپ کی تصویر کو پلس 20 فیصد پر پیش نظارہ دکھاتا ہے۔ وہ نقطہ آغاز آپ کو فوری احساس دیتا ہے کہ معتدل تضاد اضافہ کیسا لگتا ہے۔</p>\n<h2 id=\"quick-presets\">ایک کلک درست کے لیے فوری پری سیٹ</h2>\n<p>ٹول میں فوری پری سیٹ ہیں جو عام تضاد قیمتیں ایک کلک میں لگاتے ہیں۔ وہ سلائیڈر گھسیٹے بغیر مختلف سطحیں آزمانے کا تیز طریقہ ہیں۔</p>\n<p>پری سیٹ نقطہ آغاز ہیں، حتمی جواب نہیں۔ ایک کلک کریں، پیش نظارہ دیکھیں، اور پھر سلائیڈر سے باریک کریں اگر نتیجہ قریب مگر بالکل درست نہ ہو۔</p>\n<p>اختیارات تیزی سے موازنہ کرنے کے لیے پری سیٹ استعمال کریں۔ پلس 10 فیصد والا پری سیٹ پلس 30 فیصد والے کے ساتھ دکھاتا ہے کہ تصویر کاٹنے سے پہلے کتنا تضاد برداشت کر سکتی ہے۔</p>\n<h2 id=\"compare-modes\">موازنہ موڈ: پہلے، بعد، اور تقسیم</h2>\n<p>موازنہ موڈ آپ کو اصل اور ترمیم شدہ ورژن ایک ساتھ دکھاتے ہیں۔ After منظر تضاد بڑھی تصویر دکھاتا ہے، Before منظر اصل دکھاتا ہے، اور Split منظر دونوں کو ساتھ ساتھ دکھاتا ہے۔</p>\n<p>Split موازنہ تضاد کام کے لیے سب سے مفید ہے۔ یہ آپ کو بالکل دیکھنے دیتا ہے کہ کون سے سائے گہرے ہوئے اور کون سی جھلکیاں روشن ہوئیں، دونوں ورژن کے درمیان واضح لکیر کے ساتھ۔</p>\n<p>مکمل اسکرین موازنہ آپ کو سب سے بڑا منظر دیتا ہے۔ یہ تضاد ترمیم پرکھنے کا بہترین طریقہ ہے، کیونکہ مکمل سائز تصویر وہ کاٹنا دکھاتی ہے جو چھوٹا پیش نظارہ چھپاتا ہے۔</p>\n<h2 id=\"contrast-and-colour\">تضاد اور رنگ: وہ ایک دوسرے کو کیسے متاثر کرتے ہیں</h2>\n<p>تضاد رنگ کو بھی متاثر کرتا ہے جیسے لہجے کو۔ تضاد بڑھانے سے رنگ بھرپور اور زیادہ سنترپت ہو جاتے ہیں، کیونکہ گہرے گہرے ہوتے ہیں اور روشن ان کے گرد روشن ہوتے ہیں۔</p>\n<p>تضاد کم کرنے سے رنگ دھیمے ہو جاتے ہیں۔ نرم، کم تضاد والی تصویر میں ہلکے، پیسٹل لہجے ہوتے ہیں، جو پورٹریٹ اور خواب جیسے منظر کو سوٹ کرتے ہیں۔</p>\n<p>اس تعلق کا مطلب ہے کہ تضاد تبدیلی رنگ تبدیلی بھی ہے۔ جس تصویر کو زیادہ مضبوطی چاہیے، اسے تضاد چاہیے، جبکہ جس تصویر کو زیادہ رنگ چاہیے، اسے سنترپتی چاہیے۔</p>\n<h2 id=\"contrast-for-portraits\">پورٹریٹ کے لیے تضاد</h2>\n<p>پورٹریٹ کو نرم تضاد چاہیے۔ بہت زیادہ تضاد والا چہرہ سخت اور عمر رسیدہ لگتا ہے، آنکھوں کے نیچے گہرے سائے اور پیشانی پر روشن دھبوں کے ساتھ۔</p>\n<p>10 فیصد کے چھوٹے اضافے سے شروع کریں اور جلد جانچیں۔ چہرہ واضح لگنا چاہیے، ایسا نہیں جیسے سائے رنگے گئے ہوں۔</p>\n<p>منفی تضاد سخت پورٹریٹ کی مدد کر سکتا ہے۔ دوپہر کا سورج چہرے پر مضبوط سائے بناتا ہے، اور چھوٹی کمی انہیں نرم کرتی ہے بغیر مجموعی شکل کھوئے۔</p>\n<h2 id=\"contrast-for-landscapes\">منظر کے لیے تضاد</h2>\n<p>منظر کو تضاد سے سب سے زیادہ فائدہ ہوتا ہے۔ دھندلا پہاڑی منظر، دھند والی وادی، یا پھیکا آسمان، سب معتدل اضافے سے گہرائی اور ڈرامہ پاتے ہیں۔</p>\n<p>دھندلے منظر کے لیے 15 سے 25 فیصد اضافہ استعمال کریں۔ سائے گہرے ہوتے ہیں، جھلکیاں روشن ہوتی ہیں، اور منظر وہ مضبوطی پاتا ہے جو دھند نے چھین لی تھی۔</p>\n<p>جب آپ تضاد بڑھائیں تو آسمان دیکھیں۔ بادل پہلے کٹتے ہیں، بغیر شکل والے سفید خالی بن جاتے ہیں، اور کٹا آسمان اچھے منظر کو خراب کرتا ہے۔</p>\n<h2 id=\"contrast-for-screenshots\">اسکرین شاٹ اور دستاویز کے لیے تضاد</h2>\n<p>اسکرین شاٹ اور اسکین شدہ دستاویز کو پڑھنے کے لیے تضاد چاہیے۔ متن پس منظر سے نمایاں ہونا چاہیے، اور سرمئی متن والا کم تضاد اسکین پڑھنا مشکل ہے۔</p>\n<p>محفوظ کرنے والا مرحلہ چھوڑنے کے لیے اسکرین شاٹ Ctrl+V سے سیدھا چسپاں کریں۔ تصویر فوراً ایڈیٹر میں دکھائی دیتی ہے، ایڈجسٹ کرنے کے لیے تیار۔</p>\n<p>تضاد بڑھائیں جب تک متن گہرا اور پس منظر سفید نہ ہو۔ صاف سفید پس منظر پر مضبوط کالے متن والی دستاویز پڑھنا اور پرنٹ کرنا آسان ہے۔</p>\n<h2 id=\"negative-contrast\">منفی تضاد: سخت تصویریں نرم کرنا</h2>\n<p>منفی تضاد تصویر کو نرم کرتا ہے، گہرے اور ہلکے کو قریب لاتے ہوئے۔ یہ دوپہر کے سخت سورج میں لی گئی تصویر کے لیے درست انتخاب ہے۔</p>\n<p>پورٹریٹ پر مضبوط سائے نرم کرنے کے لیے مائنس 10 یا مائنس 20 فیصد جیسی قیمتیں استعمال کریں۔ چہرہ اپنی شکل رکھتا ہے، مگر سخت کنارے نرم شکل میں مٹ جاتے ہیں۔</p>\n<p>منفی تضاد خواب جیسے، نرم منظر کو بھی سوٹ کرتا ہے۔ کم تضاد والا دھندلا صبح کا منظر پرسکون اور خاموش لگتا ہے، جو تصویر کے مزاج سے میل کھاتا ہے۔</p>\n<h2 id=\"clipping-and-crushing\">جھلکیاں کاٹنا اور سائے کچلنا</h2>\n<p>کاٹنا تب ہوتا ہے جب جھلکیاں خالص سفید سے آگے دھکیلی جائیں۔ روشن بادل یا سفید قمیض میں تفصیل غائب ہو جاتی ہے، اور حصہ بے خصوصیت خالی بن جاتا ہے۔</p>\n<p>کچلنا تب ہوتا ہے جب سائے خالص کالے سے آگے دھکیلیں جائیں۔ گہرے کوٹ یا سائے والے کونے میں تفصیل غائب ہو جاتی ہے، اور حصہ ٹھوس کالا دھبہ بن جاتا ہے۔</p>\n<p>دونوں برآمد شدہ فائل میں مستقل ہیں۔ ایک بار تفصیل کٹ یا کچل جائے تو کوئی مزید ترمیم اسے واپس نہیں لا سکتی، اس لیے ڈاؤن لوڈ سے پہلے انتہاؤں کو جانچیں۔</p>\n<h2 id=\"formats-and-export\">فارمیٹ اور برآمد</h2>\n<p>ٹول عام تصویر فارمیٹ قبول کرتا ہے، بشمول JPG، PNG، WebP اور HEIC، 20 MB تک فائلیں۔ آپ اپنی ضرورت کے حساب سے JPG، PNG یا WebP کے طور پر برآمد کر سکتے ہیں۔</p>\n<p>PNG یا WebP کے طور پر برآمد کرنے سے بنیادی تصویر میں شفافیت محفوظ رہتی ہے۔ اگر آپ کا ماخذ شفاف PNG گرافک ہے تو تضاد ترمیم شدہ برآمد دیکھنے والے حصے برقرار رکھتی ہے۔</p>\n<p>تصویروں کے لیے اعلیٰ کوالٹی ترتیب پر JPG اچھا کام کرتا ہے۔ تضاد فائل سائز میں زیادہ نہیں بڑھاتا، اس لیے برآمد اصل وزن کے قریب رہتی ہے۔</p>\n<h2 id=\"contrast-vs-brightness\">تضاد بمقابلہ چمک: پہلے کون سا؟</h2>\n<p>چمک مجموعی سطح طے کرتی ہے، اور تضاد اس سطح کے گرد پھیلاؤ طے کرتا ہے۔ بہت گہری تصویر کو پہلے چمک چاہیے، کیونکہ تضاد سطح درست نہیں کر سکتا۔</p>\n<p>چپٹی مگر درست روشن تصویر کو صرف تضاد چاہیے۔ اسے روشن کرنے سے وہ روشن اور چپٹی ہو جائے گی، بہتر نہیں، اس لیے چمک مرحلہ چھوڑ دیں۔</p>\n<p>جب تصویر کو دونوں چاہییں تو پہلے چمک کریں، پھر تضاد۔ ترتیب اہم ہے، کیونکہ چمک بدلتی ہے کہ تضاد ایڈجسٹمنٹ کو کیا کرنا چاہیے۔</p>\n<h2 id=\"privacy-local-processing\">رازداری: اپ لوڈ کیے بغیر ترمیم</h2>\n<p>تمام تضاد ترمیم آپ کے براؤزر میں ہوتی ہے۔ آپ کی تصویریں کبھی سرور پر اپ لوڈ نہیں ہوتیں، جو اہم ہے جب تصویریں ذاتی ہوں، خاندانی تصویریں ہوں، یا کلائنٹ کام ہو۔</p>\n<p>یہ کلاؤڈ ایڈیٹر پر حقیقی فائدہ ہے۔ خاندانی تصویر یا نجی دستاویز کو صرف تضاد شامل کرنے کے لیے ایسے سرور پر نہیں جانا چاہیے جسے آپ دیکھ نہیں سکتے۔</p>\n<p>ٹول برآمد پر EXIF GPS ڈیٹا بھی ہٹاتا ہے۔ ٹول سے ڈاؤن لوڈ شدہ تضاد ترمیم شدہ تصویر میں کوئی ریکارڈ نہیں کہ وہ کہاں لی گئی تھی۔</p>\n<h2 id=\"common-mistakes\">تضاد ایڈجسٹ کرتے ہوئے عام غلطیاں</h2>\n<p>سب سے عام غلطی بہت زیادہ تضاد شامل کرنا ہے۔ پلس 50 فیصد یا زیادہ تک دھکیلی گئی تصویر اپنی جھلکیاں اور سائے مکمل کھو دیتی ہے، اور نتیجہ سخت، پوسٹر جیسی تصویر ہے۔</p>\n<p>دوسری غلطی تضاد سے گہری تصویر درست کرنا ہے۔ اعلیٰ تضاد والی گہری تصویر پھر بھی گہری ہے، صرف گہرے سائے کے ساتھ، اور موضوع چھپا رہتا ہے۔</p>\n<p>لوگ انتہاؤں کو جانچنا بھی بھول جاتے ہیں۔ چھوٹے پیش نظارے میں ٹھیک لگنے والا آسمان یا سایہ مکمل سائز پر کٹا یا کچلا ہو سکتا ہے، اس لیے نتیجہ ہمیشہ بڑا جانچیں۔</p>\n<h2 id=\"contrast-workflow\">صاف تضاد ترمیم کا ورک فلو</h2>\n<p>اصل فائل سے شروع کریں اور فیصلہ کریں کہ تصویر چپٹی ہے، سخت ہے، یا درست پھیلی ہوئی ہے۔ چپٹی تصویر کو اضافہ چاہیے، سخت کو کمی چاہیے، اور درست کو کچھ نہیں چاہیے۔</p>\n<p>تضاد لگائیں، پھر موازنہ منظر جانچیں۔ تقسیم منظر بالکل دکھاتا ہے کہ کون سے سائے گہرے ہوئے اور کون سی جھلکیاں روشن ہوئیں۔</p>\n<p>جھلکیاں اور سائے الگ الگ جانچیں۔ اضافے کے تحت جھلکیاں پہلے کٹتی ہیں، اور اسی حرکت کے تحت سائے پہلے کچلتے ہیں، اس لیے دونوں انتہاؤں پر توجہ چاہیے۔</p>\n<h2 id=\"contrast-for-black-white\">سیاہ سفید تصویروں کے لیے تضاد</h2>\n<p>سیاہ سفید تصویریں تضاد سے زندہ رہتی ہیں یا مرتی ہیں۔ رنگ کے بغیر تصویر رکھنے کے لیے لہجہ حد سب کچھ ہے، اور چپٹی سیاہ سفید تصویر سرمئی اور بے جان لگتی ہے۔</p>\n<p>سیاہ سفید کے لیے رنگ سے مضبوط تضاد اضافہ استعمال کریں۔ 20 سے 30 فیصد اضافہ تصویر کو وہ گہرے کالے اور روشن سفید دیتا ہے جو اسے نمایاں بناتے ہیں۔</p>\n<p>جب آپ تضاد بڑھائیں تو درمیانی لہجے دیکھیں۔ سیاہ سفید پورٹریٹ کو جلد میں ہموار سرمئی لہجے چاہییں، اور بہت زیادہ تضاد چہرے کو سخت کالے اور سفید دھبوں میں بدل دیتا ہے۔</p>\n<p>قدم بہ قدم عمل کے لیے <a href=\"/ur/blog/tasveer-ka-contrast-kaise-badlein/\">How to Adjust Image Contrast</a> دیکھیں۔ موازنہ کے لیے <a href=\"/ur/blog/brightness-vs-exposure-vs-contrast/\">Brightness vs Exposure vs Contrast: Editing Basics</a> پڑھیں، اور تضاد شامل کرنے سے پہلے گہری تصویر درست کرنے کے لیے <a href=\"/ur/tasveer-ki-brightness-badlein/\">Image Brightness Editor</a> آزمائیں۔</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"چپٹی تصویر میں کتنا تضاد شامل کروں؟","answer":"10 سے 20 فیصد سے شروع کریں اور پیش نظارہ جانچیں۔ زیادہ تر چپٹی تصویروں کو صرف چھوٹا اضافہ چاہیے، اور بڑی حرکتیں جلد جھلکیاں کاٹتی ہیں اور سائے کچلتی ہیں۔ چھوٹے قدموں میں بڑھائیں اور رک جائیں جب تصویر تفصیل کھوئے بغیر ٹھوس لگے۔"},{"question":"تضاد شامل کرنے کے بعد میری تصویر سخت کیوں لگتی ہے؟","answer":"تضاد بہت آگے دھکیلا گیا، جو سائے گہرے کرتا ہے اور جھلکیاں روشن کرتا ہے، اس نقطے سے آگے جہاں تفصیل بچتی ہے۔ سلائیڈر کم کریں جب تک جلد، آسمان اور سائے والے حصے دوبارہ بناوٹ نہ دکھائیں۔ 10 فیصد اضافہ اکثر کافی ہے۔"},{"question":"کیا تضاد بہت گہری تصویر درست کر سکتا ہے؟","answer":"نہیں۔ تضاد پھیلاؤ بدلتا ہے، سطح نہیں، اس لیے اعلیٰ تضاد والی گہری تصویر پھر بھی گہری ہے، صرف گہرے سائے کے ساتھ۔ پہلے چمک ایڈیٹر سے تصویر روشن کریں، پھر تضاد شامل کریں اگر وہ چپٹی لگے۔"},{"question":"پورٹریٹ کے لیے مثبت یا منفی تضاد استعمال کروں؟","answer":"عام طور پر 5 سے 10 فیصد کا چھوٹا مثبت اضافہ، جو چہرے کو سختی کے بغیر واضح کرتا ہے۔ سخت دوپہر کے سورج میں لی گئی پورٹریٹ کے لیے مائنس 10 سے مائنس 20 فیصد منفی تضاد مضبوط سائے نرم کرتا ہے اور جلد کو خوبصورت بناتا ہے۔"},{"question":"کیا تضاد بڑھانے سے رنگ بھی مضبوط ہو جاتے ہیں؟","answer":"جی ہاں۔ تضاد بڑھانے سے رنگ بھرپور ہو جاتے ہیں، کیونکہ گہرے گہرے ہوتے ہیں اور روشن ان کے گرد روشن ہوتے ہیں۔ اگر رنگ بہت مضبوط ہو جائیں تو بعد میں سنترپتی ایڈیٹر سے سنترپتی تھوڑی کم کریں۔"},{"question":"کیا براؤزر ٹول میں ذاتی تصویر پر تضاد ترمیم کرنا محفوظ ہے؟","answer":"جی ہاں، کیونکہ ساری پروسیسنگ آپ کے براؤزر میں مقامی طور پر ہوتی ہے اور کچھ بھی سرور پر اپ لوڈ نہیں ہوتا۔ ٹول برآمد پر EXIF GPS ڈیٹا بھی ہٹاتا ہے۔ اصل فائل رکھیں اگر آپ بعد میں مختلف تضاد سطح آزمانا چاہتے ہیں۔"}];
